param([Parameter(Mandatory)][string]$Executable,[Parameter(Mandatory)][string]$ProviderExecutable,[Parameter(Mandatory)][string]$ProjectRoot,[Parameter(Mandatory)][string]$ScratchRoot)
$ErrorActionPreference='Stop';$checks=0;$service=$null;$provider=$null
$root=Join-Path $ScratchRoot ('protocol-'+[Guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $root -Force|Out-Null
$env:TEMP=$root;$env:TMP=$root;$env:HIBERNATION_SESSION_KEY='protocol-session-fixture';$env:HIBERNATION_PROTOCOL_KEY='protocol-provider-fixture'
$headers=@{Authorization='Bearer '+$env:HIBERNATION_SESSION_KEY};$readyPath=Join-Path $root 'ready.json';$configPath=Join-Path $root '配置.json';$providerRoot=Join-Path $root 'provider'
function Check([bool]$Condition,[string]$Name){if(!$Condition){throw "CHECK FAILED: $Name"};$script:checks++;Write-Output "PASS $Name"}
function Wait-For([scriptblock]$Probe,[string]$Name,[int]$Seconds=30){$end=[DateTime]::UtcNow.AddSeconds($Seconds);while([DateTime]::UtcNow-lt$end){if(& $Probe){return};Start-Sleep -Milliseconds 50};throw "TIMEOUT: $Name"}
function Call([string]$Path,$Data=$null){$a=@{Uri=($script:origin+$Path);Headers=$headers;TimeoutSec=12};if($null-ne$Data){$a.Method='Post';$a.ContentType='application/json; charset=utf-8';$a.Body=[Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))};Invoke-RestMethod @a}
function Rejected([string]$Path,$Data,[int]$Expected){$r=Invoke-WebRequest -Uri ($script:origin+$Path) -Headers $headers -Method Post -ContentType 'application/json' -Body ([Text.Encoding]::UTF8.GetBytes(($Data|ConvertTo-Json -Depth 40 -Compress))) -SkipHttpErrorCheck;Check ($r.StatusCode-eq$Expected) "reject $Path HTTP $Expected"}
function Start-Backend{$script:service=Start-Process -FilePath $Executable -ArgumentList ('--config "'+$configPath+'" --ready-file "'+$readyPath+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root 'service.log') -RedirectStandardError (Join-Path $root 'error.log');Wait-For {if($script:service.HasExited){throw 'backend exited'};if(Test-Path $readyPath){try{return (Get-Content $readyPath -Raw|ConvertFrom-Json).pid-eq$script:service.Id}catch{}};return $false} 'backend ready';$script:origin='http://127.0.0.1:'+((Get-Content $readyPath -Raw|ConvertFrom-Json).port)}
function Stop-Backend{$null=Call '/api/shutdown' @{};$script:service.WaitForExit(15000)|Out-Null;Check $script:service.HasExited 'graceful encrypted shutdown'}
function Idle{Wait-For {!(Call '/api/chat').busy} 'turn complete'}
function Plan($Responses){@{nonce=[Guid]::NewGuid().ToString('N');responses=@($Responses|ForEach-Object{@{response=$_}})}|ConvertTo-Json -Depth 40|Set-Content -LiteralPath (Join-Path $providerRoot 'plan.json') -Encoding utf8}
function Reply([string]$Text){@{version=1;kind='reply';text=$Text;calls=@();presentation=@{speech=$false;bubble=$true}}}
function Tool([string]$Id,[string]$Name,$ToolArguments){@{id=$Id;tool=$Name;args=$ToolArguments}}
function Calls($Items){@{version=1;kind='call';text=$null;calls=@($Items);presentation=@{speech=$false;bubble=$false}}}
function Message([string]$Text){$r=Call '/api/message' @{request_id=[Guid]::NewGuid().ToString('N');text=$Text};Idle;return $r}
function Capture{Get-Content -LiteralPath (Join-Path $providerRoot 'last-request.json') -Raw|ConvertFrom-Json -Depth 50}
function Feedback{$r=Capture;@(($r.messages[-1].content|ConvertFrom-Json -Depth 50).tool_results)}
function Plugin([string]$Tool,$ToolArguments=@{}){$null=Call '/api/plugin/test' @{tool=$Tool;args=$ToolArguments};Wait-For { $script:lastPlugin=Call '/api/plugin/result';return $script:lastPlugin.state-in@('succeeded','failed','paused')} "plugin $Tool";return $script:lastPlugin.result}
try{
 New-Item -ItemType Directory -Path $providerRoot|Out-Null
 $provider=Start-Process -FilePath $ProviderExecutable -ArgumentList ('"'+$providerRoot+'"') -WindowStyle Hidden -PassThru -RedirectStandardOutput (Join-Path $root 'provider.log') -RedirectStandardError (Join-Path $root 'provider-error.log')
 Wait-For {if($provider.HasExited){throw 'fixture exited'};Test-Path (Join-Path $providerRoot 'port')} 'fixture';$fixture='http://127.0.0.1:'+([int](Get-Content (Join-Path $providerRoot 'port')))
 $config=Get-Content (Join-Path $ProjectRoot 'config/example.json') -Raw|ConvertFrom-Json -AsHashtable
 $config.dataRoot=Join-Path $root 'data';$config.characterRoot=Join-Path $ProjectRoot 'character';$config.uiRoot=Join-Path $ProjectRoot 'ui';$config.pluginRoot=Join-Path (Split-Path $Executable) 'plugins';$config.maxStartsPerHour=1000;$config.solitudeIntervalMs=600000;$config.idleBeforeSolitudeMs=600000
 $config.profiles+=@(@{id='fixture';label='Protocol fixture';protocol='chat-completions';enabled=$true;origin=$fixture;basePath='/v1';model='fixture-model';credentialEnvironment='HIBERNATION_PROTOCOL_KEY';supportsJsonSchema=$false;supportsVision=$true;timeoutMs=10000;maxOutputTokens=2048})
 $config.plugins=@{weather=@{enabled=$true;city='验证城市';geocodingOrigin=$fixture;forecastOrigin=$fixture};tts=@{enabled=$true;backend='http';origin=$fixture;maxSeconds=1;autoSpeak=$false};widget=@{enabled=$true;roam=$false};television=@{enabled=$true;volume=0}}
 $config|ConvertTo-Json -Depth 40|Set-Content $configPath -Encoding utf8;Start-Backend
 $null=Call '/api/model' @{id='fixture'}
 Plan @('not JSON',(Calls @((Tool 'remember' 'memory.remember' @{kind='conversation';text='唯一的加密记忆标记-协议验证';source_ids=@('${event_id}')}),(Tool 'state' 'state.propose' @{activity='withdrawing';intensity=-0.7;source_id='${event_id}'}),(Tool 'schedule' 'schedule.create' @{id='later';topic='重新想想星星';after_ms=600000}),(Tool 'draft' 'workspace.write' @{path='protocol-note.md';content='可见草稿，与内部记忆分开。'}))),(Reply '我把这个问题留下了。'))
 $first=Message '唯一的原始交谈标记-协议验证';$chat=Call '/api/chat';Check ($chat.messages.Count-eq2-and$chat.messages[-1].text-eq'我把这个问题留下了。') 'repair and tool loop expose only final dialogue'
 $feedback=Feedback;Check (@($feedback|Where-Object ok -eq $true).Count-eq4) 'all four approved tool receipts returned to model'
 $memoryId=$feedback[0].result.id;Check ((Call '/api/memories').memories[0].sources[0].id-eq$first.event_id) 'memory uses authentic input provenance'
 Check (Test-Path (Join-Path $config.dataRoot 'drafts/protocol-note.md')) 'workspace tool writes permitted draft'
 Check (!(Call '/api/chat').busy) 'future schedule does not block conversation'
 Plan @((Calls @((Tool 'write' 'workspace.write' @{path='unicode.txt';content=('星'*1000)}),(Tool 'read' 'workspace.read' @{mount='drafts';path='unicode.txt';offset=1;length=256}))),(Reply '只取出这一小段。'));$null=Message '分段素材读取验证';$segment=(Feedback)[1];Check ($segment.ok-and$segment.result.offset-eq0-and$segment.result.next_offset-eq255-and!$segment.result.eof) 'workspace chunks align byte offsets to UTF8 boundaries';Check ([Text.Encoding]::UTF8.GetByteCount($segment.result.content)-eq255) 'workspace chunk obeys requested byte budget';$observation=Call '/api/archive' @{id=$segment.source_id};Check ($observation.records[0].data.kind-eq'tool_observation') 'workspace reads produce authentic encrypted observation sources'
 $schedule=@((Call '/api/state').jobs|Where-Object id -eq 'routine.later');Check ($schedule.Count-eq1) 'model created durable future schedule'
 $beforeSilence=(Call '/api/chat').messages.Count;Plan @(@{version=1;kind='silence';text=$null;calls=@()});$null=Message '允许这次不回答。';Check ((Call '/api/chat').messages.Count-eq($beforeSilence+1)) 'silence creates no empty assistant bubble'
 Plan @((Calls @((Tool 'bad' 'shell.run' @{command='forbidden'}),(Tool 'badargs' 'workspace.write' @{path='../character/persona.json';content='forbidden'}),(Tool 'fake' 'memory.remember' @{kind='outer';text='编造事实';source_ids=@('invented')}))),(Reply '这些操作没有获准。'))
 $null=Message '异常工具验证';$feedback=Feedback;Check (@($feedback|Where-Object ok -eq $false).Count-eq3) 'unknown tool path traversal and fabricated sources fail independently'
 Check ((Call '/api/memories').memories.Count-eq1) 'rejected commands add no memory'
 Plan @((Calls @((Tool 'same' 'workspace.write' @{path='once.md';content='first'}))),(Calls @((Tool 'same' 'workspace.write' @{path='once.md';content='second'}))),(Reply '调用编号冲突已处理。'))
 $null=Message '重复调用验证';Check ((Get-Content (Join-Path $config.dataRoot 'drafts/once.md') -Raw)-eq'first') 'reused call id cannot execute changed arguments';Check ((Feedback)[0].error.code-eq'call_id_reused_with_different_arguments') 'duplicate call conflict is returned'
 Plan @((Calls @((Tool 'revise' 'memory.revise' @{id=$memoryId;expected_revision=1;kind='summary';text='修订后的加密摘要';source_ids=@('${event_id}')}))),(Calls @((Tool 'forget' 'memory.forget' @{id=$memoryId}))),(Reply '保留经历，但不再主动提取它。'))
 $null=Message '修订与遗忘验证';Check ((Call '/api/memories').memories[0].revision-eq2) 'memory revision appended';Check (!(Call '/api/memories').memories[0].accessible) 'forget changes accessibility only';$raw=Call '/api/archive' @{id=$first.event_id};Check ($raw.records[0].data.text-eq'唯一的原始交谈标记-协议验证') 'raw evidence survives revision and forgetting'
 Plan @((Calls @((Tool 'weather' 'weather.current' @{}))),(Calls @((Tool 'experience' 'memory.remember' @{kind='outer';text='外层天气观测：热雨。';source_ids=@('${last_source_id}')}))),(Calls @((Tool 'observe' 'state.observe' @{}))),(Reply '外面的雨让节奏慢了一点。'))
 $null=Message '天气经历验证';$state=(Feedback)[0].result;Check ($state.weather_code-eq63) 'weather event reaches continuous state';Check ($state.mood-ge0.49-and$state.mood-le0.51) 'weather does not abruptly replace mood';Check ($state.weather_comfort-lt1) 'weather influences bounded energy and openness parameters'
 $weatherMemory=@((Call '/api/memories').memories|Where-Object kind -eq outer)[0];Check ($weatherMemory.sources[0].kind-eq'tool_observation') 'weather memory cites actual plugin observation'
 $video=Join-Path $config.dataRoot 'materials/clip.mp4';Copy-Item (Join-Path $providerRoot 'clip.mp4') $video
 $opened=Plugin 'television.open' @{source='clip.mp4';title='Synthetic test'};Check $opened.ok 'real television decodes authorized local movie'
 Wait-For {$script:observedFrame=Plugin 'television.observe' @{include_frame=$true};return $null-ne$script:observedFrame.result.image} 'first encoded TV frame' 10;$frame=$script:observedFrame;Check ($frame.ok-and$frame.result.image.mime_type-eq'image/jpeg'-and$frame.result.image.base64.Length-gt100) 'TV observation contains actual encoded frame'
 $null=Plugin 'television.control' @{action='pause'};$null=Plugin 'television.control' @{action='seek';seconds=1};$frame=Plugin 'television.observe' @{include_frame=$true};Check ($frame.result.state-eq'paused'-and$frame.result.frame_time_seconds-ge0.95) 'paused seek presents new target frame'
 $denied=Plugin 'television.open' @{source='../archive/records.sqlite'};Check (!$denied.ok) 'TV cannot read outside materials workspace'
 $opened=Plugin 'television.open' @{source=($fixture+'/clip.mp4')};Check $opened.ok 'TV plays actual direct URL through engine demux'
 Plan @((Calls @((Tool 'frame' 'television.observe' @{include_frame=$true}))),(Reply '只分析实际提供的画面。'))
 $null=Message '视觉输入验证';$capture=Capture;Check ($capture.messages[-1].content[1].image_url.url.StartsWith('data:image/jpeg;base64,')) 'real frame attached using multimodal provider shape'
 $null=Plugin 'television.control' @{action='pause'}
 $speech=Plugin 'speech.speak' @{text='语音时长验证';max_seconds=1};Check ($speech.ok-and$speech.result.started) 'HTTP WAV begins actual local playback';Start-Sleep -Milliseconds 1300;$spoken=Plugin 'speech.status';Check (!$spoken.result.active-and$spoken.result.last_duration_seconds-le1.3-and$spoken.result.last_duration_seconds-ge0.7) 'playback enforces one second duration limit'
 $widget=Plugin 'widget.status';Check (!$widget.result.desktop) 'headless integration creates no desktop overlay';$widget=Plugin 'widget.move' @{x=0.5;y=0.5};Check (!$widget.ok-and$widget.error.code-eq'desktop_required') 'desktop-only action reports explicit unavailable result'
 $settings=(Call '/api/dashboard').settings;$bad=$settings|ConvertTo-Json -Depth 40|ConvertFrom-Json -AsHashtable;$bad.plugins.tts.rate=999;Rejected '/api/settings' @{settings=$bad} 400;Check ((Call '/api/dashboard').plugins.Where({$_.enabled}).Count-eq4) 'rejected plugin reconfiguration preserves all enabled plugins'
 $bad=$settings|ConvertTo-Json -Depth 40|ConvertFrom-Json -AsHashtable;$bad.draftsRoot=Join-Path $config.dataRoot 'archive';Rejected '/api/settings' @{settings=$bad} 400
 Plan @(@{version=1;kind='silence';text=$null;calls=@()})
 $null=Plugin 'television.control' @{action='seek';seconds=7.7};$null=Plugin 'television.control' @{action='play'}
 Wait-For {try{$r=Capture;$data=$r.messages[-1].content|ConvertFrom-Json -Depth 40;return $data.event_kind-eq'outer_event'-and$data.input.Contains('television.ended')}catch{return $false}} 'movie completion reaches role event loop' 15
 Idle;Check ((Call '/api/chat').messages[-1].text-eq'只分析实际提供的画面。') 'movie completion may remain silent without an extra chat bubble'
 $null=Plugin 'television.control' @{action='stop'}
 $secret='saved-secret-fixture-for-dpapi';$null=Call '/api/secret' @{profile_id='fixture';value=$secret};Check (!(Get-Content $configPath -Raw).Contains($secret)) 'dashboard key absent from config';Check (!(Call '/api/dashboard'|ConvertTo-Json -Depth 40).Contains($secret)) 'dashboard never returns saved key'
 $null=Call '/api/control' @{paused=$true};Stop-Backend
 $bytes=[IO.File]::ReadAllBytes((Join-Path $config.dataRoot 'archive/records.sqlite'));$text=[Text.Encoding]::UTF8.GetString($bytes);Check (!$text.Contains('唯一的原始交谈标记')-and!$text.Contains('唯一的加密记忆标记')) 'original and derived memory payloads encrypted at rest'
 $journal=[Text.Encoding]::UTF8.GetString([IO.File]::ReadAllBytes((Join-Path $config.dataRoot 'archive/events.sqlite')));Check (!$journal.Contains('唯一的原始交谈标记')-and!$journal.Contains('data:image/')) 'event index contains no conversation or frame payload'
 Remove-Item Env:HIBERNATION_PROTOCOL_KEY;Start-Backend;$dashboard=Call '/api/dashboard';Check $dashboard.paused 'pause survives real process restart';Check $dashboard.settings.profiles.Where({$_.id-eq'fixture'})[0].credentialConfigured 'DPAPI model key restores without parent environment'
 Check ((Call '/api/memories').memories.Count-eq2) 'memory revisions survive restart';$chat=Call '/api/chat';Check ($chat.messages[-1].text-eq'只分析实际提供的画面。') 'dialogue survives restart without exposing instructions'
 $null=Call '/api/control' @{paused=$false};Plan @((Calls @((Tool 'state' 'state.observe' @{}))),(Reply '继续。'));$null=Message '重启后的连续性';$restored=(Feedback)[0].result;Check ([Math]::Abs($restored.openness-$state.openness)-lt0.05) 'continuous values survive restart without an offline jump'
 $settings=(Call '/api/dashboard').settings|ConvertTo-Json -Depth 40|ConvertFrom-Json -AsHashtable;foreach($id in @('television','widget','tts','weather')){$settings.plugins[$id].enabled=$false};$null=Call '/api/settings' @{settings=$settings};Check ((Call '/api/dashboard').plugins.Where({$_.enabled}).Count-eq0) 'all plugins unload independently from core'
 Plan @((Calls @((Tool 'missing' 'weather.current' @{}))),(Reply '现在没有天气插件。'));$null=Message '无插件模式';Check ((Feedback)[0].error.code-eq'tool_not_available') 'disabled capability removed from model tool access'
 $settings.profiles.Where({$_.id-eq'fixture'})[0].supportsJsonSchema=$true;$null=Call '/api/settings' @{settings=$settings};Plan @('invalid native schema output',(Calls @((Tool 'native' 'memory.search' @{query='不存在的内容';limit=$null}))),(Reply '严格结构接口验证完成。'));$null=Message '严格结构输出验证';$capture=Capture;Check ($capture.response_format.json_schema.strict-and$capture.response_format.json_schema.schema.required-contains'presentation') 'native structured schema uses closed required fields';Check ((Feedback)[0].ok) 'known optional null normalized before local tool validation';Check ((Call '/api/chat').messages[-1].text-eq'严格结构接口验证完成。') 'native invalid output repairs before executing valid command'
 Stop-Backend
 [pscustomobject]@{completed=$true;checks=$checks;root=$root;timestamp=[DateTime]::UtcNow.ToString('O')}|ConvertTo-Json|Set-Content (Join-Path $root 'acceptance.json') -Encoding utf8;Write-Output "Protocol integration passed: $checks checks. Evidence: $root"
}finally{if($service){$service.Refresh();if(!$service.HasExited){try{$null=Call '/api/shutdown' @{};$service.WaitForExit(5000)|Out-Null}catch{};$service.Refresh();if(!$service.HasExited){Stop-Process -Id $service.Id}}};if($provider){$provider.Refresh();if(!$provider.HasExited){Stop-Process -Id $provider.Id}}}
